import { z } from 'zod';

/** RFC 4122 UUID, as generated by Postgres `gen_random_uuid()` and Supabase Auth. */
export const uuidSchema = z.uuid();

/** Calendar date, `YYYY-MM-DD`. Always interpreted in the office timezone by the server. */
export const isoDateSchema = z.iso.date();

/** Wall-clock time of day, `HH:MM` or `HH:MM:SS`. */
export const timeOfDaySchema = z
  .string()
  .regex(/^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$/, 'Expected HH:MM or HH:MM:SS');

export const latitudeSchema = z.number().min(-90).max(90);
export const longitudeSchema = z.number().min(-180).max(180);

export const paginationSchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(200).default(50),
});
export type Pagination = z.infer<typeof paginationSchema>;

export const idempotencyKeySchema = z
  .string()
  .min(8)
  .max(128)
  .regex(/^[A-Za-z0-9_.:-]+$/, 'Idempotency-Key may only contain letters, digits and _ . : -');
